public class Weekly_Assignment_Sum_Of_Even {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int num=1;
		int sum =0;
		for(;num<=50;) 
		{
			if(num%2==0) 
			{
				
//				System.out.println (num +" is even number");
				
				sum=sum+num;;
						}
			
			num++;
			System.out.println(sum);
			
		}

	}

}


	
